package org.securemail.identity;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import org.securemail.ecosystem.protocol.IdentityProtocol.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class IdentityHttpServerTest {
    @TempDir Path temp;IdentityStore store;IdentityHttpServer server;KeyPair service,root,device,recovery,app;HttpClient client;String account,deviceId;long generation;
    static KeyPair pair()throws Exception{return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}
    static byte[] key(KeyPair k){return k.getPublic().getEncoded();}
    @BeforeEach void setup()throws Exception {service=pair();root=pair();device=pair();recovery=pair();app=pair();account=IdentityProtocol.id(key(root));deviceId=IdentityProtocol.id(key(device));byte[] audit=new byte[32];new SecureRandom().nextBytes(audit);store=new IdentityStore(temp.resolve("identity.db"),service,audit,Clock.systemUTC());server=new IdentityHttpServer(new InetSocketAddress("127.0.0.1",0),store,service);server.start();client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();}
    @AfterEach void close()throws Exception {server.close();store.close();}
    Map<String,Object> rpc(String operation,Map<String,Object> data)throws Exception {String n=IdentityProtocol.nonce();byte[] request=IdentityJson.bytes(Map.of("operation",operation,"nonce",n,"data",data));HttpResponse<byte[]> response=client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+server.port()+"/identity/v1")).header("Content-Type","application/json").timeout(Duration.ofSeconds(3)).POST(HttpRequest.BodyPublishers.ofByteArray(request)).build(),HttpResponse.BodyHandlers.ofByteArray());byte[] signature=IdentityProtocol.unb64(response.headers().firstValue("AEGIS-Signature").orElseThrow(),64);assertTrue(IdentityProtocol.verify(key(service),IdentityProtocol.response(store.audience(),n,request,response.body()),signature));Map<String,Object> document=IdentityJson.parse(response.body());if(Boolean.TRUE.equals(document.get("ok"))){@SuppressWarnings("unchecked")Map<String,Object> result=(Map<String,Object>)document.get("data");return result;}@SuppressWarnings("unchecked")Map<String,Object> error=(Map<String,Object>)document.get("error");throw new IdentityException((String)error.get("code"));}
    void register()throws Exception {long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] payload=IdentityProtocol.registration(store.audience(),key(root),key(device),key(recovery),"Николай",time,nonce);Map<String,Object> result=rpc("register",Map.of("accountKey",IdentityProtocol.b64(key(root)),"deviceKey",IdentityProtocol.b64(key(device)),"recoveryKey",IdentityProtocol.b64(key(recovery)),"nickname","Николай","time",time,"nonce",nonce,"accountProof",IdentityProtocol.b64(IdentityProtocol.sign(root.getPrivate(),payload)),"deviceProof",IdentityProtocol.b64(IdentityProtocol.sign(device.getPrivate(),payload))));assertEquals(account,result.get("accountId"));generation=(Long)result.get("generation");}
    Capability capability(App target,Scope scope)throws Exception {long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] payload=IdentityProtocol.capabilityRequest(store.audience(),account,deviceId,generation,target,key(app),EnumSet.of(scope),600000,time,nonce);Map<String,Object> request=new LinkedHashMap<>();request.put("accountId",account);request.put("deviceId",deviceId);request.put("generation",generation);request.put("appId",target.name());request.put("proofKey",IdentityProtocol.b64(key(app)));request.put("capabilities",List.of(scope.name()));request.put("ttl",600000);request.put("time",time);request.put("nonce",nonce);request.put("deviceProof",IdentityProtocol.b64(IdentityProtocol.sign(device.getPrivate(),payload)));request.put("appProof",IdentityProtocol.b64(IdentityProtocol.sign(app.getPrivate(),payload)));return IdentityProtocol.decodeCapability((String)rpc("issueCapability",request).get("capability"));}
    @Test void signedLoopbackRegisterIssueAndDigestAuthorizationActuallyWork()throws Exception {register();Capability cap=capability(App.LIBRARY,Scope.LIBRARY_READ);long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] digest=IdentityProtocol.digest("library.material=uuid".getBytes(StandardCharsets.UTF_8));Map<String,Object> request=Map.of("capability",IdentityProtocol.encodeCapability(cap),"action","library.read","bodySha256",IdentityProtocol.b64(digest),"time",time,"nonce",nonce,"proof",IdentityProtocol.b64(IdentityProtocol.sign(app.getPrivate(),IdentityProtocol.requestDigest(cap,"library.read",digest,time,nonce))));Map<String,Object> context=rpc("authorizeDigest",request);assertEquals(account,context.get("accountId"));assertEquals(account,IdentityProtocol.id(IdentityProtocol.unb64((String)context.get("accountPublicKey"),44)));assertEquals("Николай",context.get("nickname"));assertFalse(context.containsKey("ownerBadge"));assertEquals("LIBRARY",context.get("appId"));assertEquals(true,rpc("isActive",Map.of("capability",IdentityProtocol.encodeCapability(cap))).get("active"));assertEquals("REPLAY",assertThrows(IdentityException.class,()->rpc("authorizeDigest",request)).code());}
    @Test void isActiveRecheckGivesNoIdentityMetadataAndTurnsFalseAfterLogin()throws Exception {register();Capability cap=capability(App.MAIL,Scope.MAIL_READ);long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();rpc("login",Map.of("accountId",account,"deviceId",deviceId,"time",time,"nonce",nonce,"proof",IdentityProtocol.b64(IdentityProtocol.sign(device.getPrivate(),IdentityProtocol.login(store.audience(),account,deviceId,time,nonce)))));Map<String,Object> state=rpc("isActive",Map.of("capability",IdentityProtocol.encodeCapability(cap)));assertEquals(Map.of("active",false),state);assertEquals(Map.of("active",false),rpc("isActive",Map.of("capability","invalid")));}
    @Test void wrongMethodDuplicateKeysMassAssignmentAndMalformedUtf8Refused()throws Exception {HttpResponse<byte[]> get=client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+server.port()+"/identity/v1")).GET().build(),HttpResponse.BodyHandlers.ofByteArray());assertEquals(400,get.statusCode());byte[][] bodies={"{\"operation\":\"register\",\"operation\":\"login\",\"nonce\":\"x\",\"data\":{}}".getBytes(StandardCharsets.UTF_8),new byte[]{'{','"','a','"',':','"',(byte)0xc0,(byte)0xaf,'"','}'},IdentityJson.bytes(Map.of("operation","isActive","nonce",IdentityProtocol.nonce(),"data",Map.of("capability","bad"),"owner",true))};for(byte[] b:bodies){HttpResponse<byte[]> r=client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+server.port()+"/identity/v1")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofByteArray(b)).build(),HttpResponse.BodyHandlers.ofByteArray());assertEquals(400,r.statusCode());}}
    @Test void remoteListeningAddressAndWrongServiceKeyForbidden()throws Exception {assertThrows(java.io.IOException.class,()->new IdentityHttpServer(new InetSocketAddress("0.0.0.0",0),store,service));assertThrows(java.io.IOException.class,()->new IdentityHttpServer(new InetSocketAddress("127.0.0.1",0),store,pair()));}
    @Test void actualHttpFirstDelegationAndReauthenticationUseOnlyTypedProofs()throws Exception {
        register();IdentityStore.OwnerChallenge ownerChallenge=store.ownerChallenge(account);store.bootstrapOwner(account,ownerChallenge.challenge(),IdentityProtocol.sign(root.getPrivate(),IdentityProtocol.ownerBootstrap(store.audience(),account,ownerChallenge.challenge(),ownerChallenge.expiresAt())));
        Capability accountCap=capability(App.AEGIS,Scope.ACCOUNT_READ);long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();Map<String,Object> step=rpc("stepUpChallenge",Map.of("capability",IdentityProtocol.encodeCapability(accountCap),"time",time,"nonce",nonce,"proof",IdentityProtocol.b64(IdentityProtocol.sign(app.getPrivate(),IdentityProtocol.request(accountCap,"account.read",new byte[0],time,nonce)))));byte[] stepBytes=IdentityProtocol.stepUp(store.audience(),account,deviceId,(String)step.get("challenge"),(Long)step.get("expiresAt"));rpc("stepUp",Map.of("accountId",account,"deviceId",deviceId,"generation",generation,"challenge",step.get("challenge"),"accountProof",IdentityProtocol.b64(IdentityProtocol.sign(root.getPrivate(),stepBytes)),"deviceProof",IdentityProtocol.b64(IdentityProtocol.sign(device.getPrivate(),stepBytes))));Capability ownerCap=capability(App.AEGIS,Scope.ADMIN);
        KeyPair targetRoot=pair(),targetDevice=pair(),targetRecovery=pair();long t=System.currentTimeMillis();String n=IdentityProtocol.nonce();byte[] register=IdentityProtocol.registration(store.audience(),key(targetRoot),key(targetDevice),key(targetRecovery),"Второй",t,n);IdentityStore.Session targetSession=store.register(key(targetRoot),key(targetDevice),key(targetRecovery),"Второй",t,n,IdentityProtocol.sign(targetRoot.getPrivate(),register),IdentityProtocol.sign(targetDevice.getPrivate(),register));String proposalNonce=IdentityProtocol.nonce();long proposalTime=System.currentTimeMillis();byte[] proposal=IdentityProtocol.firstDelegateProposal(store.audience(),account,targetSession.accountId(),"Независимый администратор",proposalTime,proposalNonce);Map<String,Object> challenge=rpc("firstDelegateChallenge",Map.of("capability",IdentityProtocol.encodeCapability(ownerCap),"targetAccountId",targetSession.accountId(),"roleName","Независимый администратор","time",proposalTime,"nonce",proposalNonce,"proof",IdentityProtocol.b64(IdentityProtocol.sign(app.getPrivate(),IdentityProtocol.requestDigest(ownerCap,"admin.execute",IdentityProtocol.digest(proposal),proposalTime,proposalNonce)))));
        byte[] consent=IdentityProtocol.firstDelegateConsent((String)challenge.get("audience"),(String)challenge.get("ownerAccountId"),(String)challenge.get("ownerDeviceId"),(Long)challenge.get("ownerGeneration"),(String)challenge.get("targetAccountId"),(String)challenge.get("targetDeviceId"),(Long)challenge.get("targetGeneration"),(String)challenge.get("roleName"),(String)challenge.get("challenge"),(Long)challenge.get("expiresAt"));assertArrayEquals(consent,IdentityProtocol.unb64((String)challenge.get("proofBytes"),2048));assertEquals(true,rpc("firstDelegateComplete",Map.of("challenge",challenge.get("challenge"),"ownerRootProof",IdentityProtocol.b64(IdentityProtocol.sign(root.getPrivate(),consent)),"ownerDeviceProof",IdentityProtocol.b64(IdentityProtocol.sign(device.getPrivate(),consent)),"targetRootProof",IdentityProtocol.b64(IdentityProtocol.sign(targetRoot.getPrivate(),consent)),"targetDeviceProof",IdentityProtocol.b64(IdentityProtocol.sign(targetDevice.getPrivate(),consent)))).get("delegated"));
        root=targetRoot;device=targetDevice;recovery=targetRecovery;app=pair();account=targetSession.accountId();deviceId=targetSession.deviceId();generation=targetSession.generation();assertTrue(store.isActive(capability(App.AEGIS,Scope.ADMIN)));Capability ownProfile=capability(App.AEGIS,Scope.ACCOUNT_READ);long profileTime=System.currentTimeMillis();String profileNonce=IdentityProtocol.nonce();Map<String,Object> profile=rpc("profile",Map.of("capability",IdentityProtocol.encodeCapability(ownProfile),"time",profileTime,"nonce",profileNonce,"proof",IdentityProtocol.b64(IdentityProtocol.sign(app.getPrivate(),IdentityProtocol.request(ownProfile,"account.read",new byte[0],profileTime,profileNonce)))));assertEquals(true,profile.get("delegatedAdministrator"));assertEquals(false,profile.get("ownerBadge"));assertEquals("Независимый администратор",profile.get("delegatedRoleName"));
    }
    @Test void managedAccountUsesSignedHttpAndExposesOnlyBooleanToPinnedRelay()throws Exception {register();KeyPair relay=pair();String serviceId=IdentityProtocol.id(key(relay));long time=System.currentTimeMillis();String n=IdentityProtocol.nonce();Map<String,Object> data=Map.of("serviceKey",IdentityProtocol.b64(key(relay)),"accountId",account,"time",time,"nonce",n,"proof",IdentityProtocol.b64(IdentityProtocol.sign(relay.getPrivate(),IdentityProtocol.managedAccountQuery(store.audience(),serviceId,account,time,n))));assertEquals("DENIED",assertThrows(IdentityException.class,()->rpc("managedAccount",data)).code());store.allowRelayService(key(relay),serviceId);assertEquals(Map.of("managed",true),rpc("managedAccount",data));assertEquals("REPLAY",assertThrows(IdentityException.class,()->rpc("managedAccount",data)).code());store.revokeRelayService(serviceId);assertEquals("DENIED",assertThrows(IdentityException.class,()->rpc("managedAccount",data)).code());}
    @Test void bootstrapInspectionRequiresExistingOperatorChallengeAndNeverCompletesOverHttp()throws Exception {
        register();Capability cap=capability(App.AEGIS,Scope.ACCOUNT_READ);IdentityStore.OwnerChallenge c=store.ownerChallenge(account);long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] query=IdentityProtocol.ownerBootstrapInspection(store.audience(),c.challenge(),time,nonce);Map<String,Object> request=Map.of("capability",IdentityProtocol.encodeCapability(cap),"challenge",c.challenge(),"time",time,"nonce",nonce,"proof",IdentityProtocol.b64(IdentityProtocol.sign(app.getPrivate(),IdentityProtocol.requestDigest(cap,"account.read",IdentityProtocol.digest(query),time,nonce))));Map<String,Object> response=rpc("ownerBootstrapInspect",request);OwnerBootstrap bootstrap=IdentityProtocol.decodeOwnerBootstrap(IdentityProtocol.unb64((String)response.get("bootstrap"),1024));assertEquals(account,bootstrap.accountId);assertEquals(c.expiresAt(),bootstrap.expiresAt);assertFalse((Boolean)store.profile(account).get("ownerBadge"));assertThrows(IdentityException.class,()->rpc("ownerBootstrapInspect",request));assertEquals("NOT_FOUND",assertThrows(IdentityException.class,()->rpc("ownerBootstrapComplete",Map.of())).code());assertThrows(IllegalArgumentException.class,()->IdentityProtocol.decodeOwnerTransfer(IdentityProtocol.ownerBootstrapBytes(bootstrap)));store.bootstrapOwner(account,c.challenge(),IdentityProtocol.sign(root.getPrivate(),IdentityProtocol.ownerBootstrapBytes(bootstrap)));assertTrue((Boolean)store.profile(account).get("ownerBadge"));assertFalse(store.isActive(cap));
    }
    @Test void strictJsonRejectsHugeNumbersFractionsDeepTreesAndLoneSurrogate(){for(String text:List.of("{\"x\":1.0}","{\"x\":-1}","{\"x\":9223372036854775808}","{\"x\":\"\\ud800\"}","{\"x\":"+"[".repeat(20)+"0"+"]".repeat(20)+"}")){assertThrows(java.io.IOException.class,()->IdentityJson.parse(text.getBytes(StandardCharsets.UTF_8)));}}
}
